// Deterministic Bitrix24 failure simulator, used by tests to exercise lib b24_call retries.
//   qle.<N>.<run>.json  -> first N calls: 503 QUERY_LIMIT_EXCEEDED, then success
//   otl.<N>.<run>.json  -> first N calls: 429 OPERATION_TIME_LIMIT (operating_reset_at = now+3s)
//   err200.<run>.json   -> HTTP 200 with {"error":"ACCESS_DENIED"} (error hidden in a 200)
//   ok.<run>.json       -> success
const m = String($json.params.method ?? '').replace(/\.json$/, '');
const [kind, nStr] = m.split('.');
const stat = $getWorkflowStaticData('global');
stat.calls = stat.calls ?? {};
const seen = (stat.calls[m] = (stat.calls[m] ?? 0) + 1);
const now = Date.now() / 1000;
const time = { start: now, finish: now + 0.01, duration: 0.01, processing: 0.005, operating: 1.5, operating_reset_at: Math.floor(now + 3) };
const n = Number(nStr ?? 0);
let status = 200, body = { result: { echo: $json.body ?? null, call: seen }, time };
if (kind === 'qle' && seen <= n) { status = 503; body = { error: 'QUERY_LIMIT_EXCEEDED', error_description: 'Too many requests', time }; }
if (kind === 'otl' && seen <= n) { status = 429; body = { error: 'OPERATION_TIME_LIMIT', error_description: 'Method is blocked due to operation time limit.', time }; }
if (kind === 'err200') { body = { error: 'ACCESS_DENIED', error_description: 'Access denied (mock)', time }; }
return [{ json: { status, body } }];
